<style>
	.scene {
		position: relative;
		width: 100%;
		max-width: 720px;
		height: 400px;
		background: var(--screen);
		border: 4px solid var(--ink);
		border-radius: 10px;
		overflow: hidden;
		box-sizing: border-box;
	}
	.cloud {
		position: absolute;
		background: #ffffff;
		border: 3px solid var(--ink);
	}
	.ground {
		position: absolute;
		left: 0;
		right: 0;
		bottom: 0;
		height: 96px;
		background: var(--grass);
		border-top: 4px solid var(--ink);
	}
	.trainer {
		position: absolute;
		left: 16%;
		bottom: 90px;
		width: 128px;
		height: 192px;
	}
	.mons {
		position: absolute;
		right: 14%;
		bottom: 92px;
		width: 128px;
		height: 128px;
	}
	svg {
		display: block;
		width: 100%;
		height: 100%;
	}
	.mon {
		position: absolute;
		left: 0;
		bottom: 0;
		opacity: 0;
		animation: monCycle 12s linear infinite;
	}
	.mon2 {
		animation-delay: 3s;
	}
	.mon3 {
		animation-delay: 6s;
	}
	.mon4 {
		animation-delay: 9s;
	}
	@keyframes monCycle {
		0% {
			transform: translateX(140%);
			opacity: 0;
		}
		5%,
		22% {
			transform: translateX(0);
			opacity: 1;
		}
		25%,
		100% {
			transform: translateX(-40%);
			opacity: 0;
		}
	}
	.bob {
		animation: bob 1.2s steps(2, end) infinite;
	}
	@keyframes bob {
		0%,
		100% {
			transform: translateY(0);
		}
		50% {
			transform: translateY(-4px);
		}
	}

	/* Phone layout (design/LoginMobile.dc.html). */
	@media (max-width: 600px) {
		.scene {
			height: 260px;
		}
		.ground {
			height: 64px;
		}
		.trainer {
			bottom: 58px;
			width: 80px;
			height: 120px;
		}
		.mons {
			bottom: 60px;
			width: 80px;
			height: 80px;
		}
	}

	@media (prefers-reduced-motion: reduce) {
		.mon,
		.bob {
			animation: none;
		}
		.mon1 {
			opacity: 1;
		}
	}
</style>
